import{_ as t,o,c as d,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"打印模板","description":"","frontmatter":{},"headers":[],"relativePath":"backend/printing.md","filePath":"backend/printing.md","lastUpdated":1786518498000}'),a={name:"backend/printing.md"};function c(i,e,n,l,s,p){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="打印模板" tabindex="-1">打印模板 <a class="header-anchor" href="#打印模板" aria-label="Permalink to &quot;打印模板&quot;">​</a></h1><p>打印能力由独立模块 <code>modules/XiHan.BasicApp.Printing</code> 承载（后端）与 <code>frontend/src/modules/printing</code> + <code>@xihan/printing</code> 功能包承载（前端）：可视化设计打印模板、按编码解析、浏览器预览打印与本机静默直打。不需要此能力的部署可整体卸载模块（见仓库 README「卸载可选模块」）。</p><h2 id="能力与边界" tabindex="-1">能力与边界 <a class="header-anchor" href="#能力与边界" aria-label="Permalink to &quot;能力与边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>依赖</th><th>说明</th></tr></thead><tbody><tr><td>模板设计器</td><td>仅浏览器</td><td>hiprint 可视化拖拽设计，模板 JSON 存 <code>Sys_Print_Template</code></td></tr><tr><td>浏览器预览打印</td><td>仅浏览器</td><td><code>previewPrintByCode</code> 打开系统打印预览窗口，任何部署形态可用</td></tr><tr><td>打印机列表 / 静默直打</td><td><strong>electron-hiprint 桌面客户端</strong></td><td><code>listPrinters</code> / <code>refreshPrinters</code> / <code>directPrintByCode</code> 要求每台操作机安装并运行 <a href="https://gitee.com/CcSimple/electron-hiprint" target="_blank" rel="noreferrer">electron-hiprint</a> 客户端，前端经 WebSocket（默认 <code>http://localhost:17521</code>）连接；客户端未连接时这三条路径明确报错，不静默回退</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">部署前提</p><p>静默直打是<strong>企业内网桌面场景</strong>的能力：纯 Web 部署（用户不装桌面客户端）只有设计器与浏览器预览可用。客户端连接地址与令牌经 Vite 环境变量 <code>VITE_HIPRINT_HOST</code> / <code>VITE_HIPRINT_TOKEN</code> 配置（省略时用内置默认值 <code>http://localhost:17521</code> / <code>vue-plugin-hiprint</code>）。该令牌随前端产物分发、可在浏览器端看到，仅是本机客户端的握手口令，不是保密凭据。</p></div><h2 id="作用域模型" tabindex="-1">作用域模型 <a class="header-anchor" href="#作用域模型" aria-label="Permalink to &quot;作用域模型&quot;">​</a></h2><p>模板分两种作用域，解析顺序由 <code>PrintTemplateScope</code> 控制（<code>Application/Services/PrintTemplateResolver.cs</code>）：</p><ul><li><strong>Tenant</strong>：租户私有模板，<code>TenantId</code> = 当前租户；</li><li><strong>Global</strong>：平台全局模板（<code>TenantId = 0</code>），<code>AllowTenantUse = true</code> 时对业务租户开放解析；</li><li><strong>Auto</strong>（默认）：先找租户私有，未命中回退开放的全局模板。</li></ul><p>同租户内启用模板的 <code>TemplateCode</code> 唯一；解析结果带分布式缓存（30 分钟，写路径经事务感知失效器整体清除）。</p><h2 id="权限码" tabindex="-1">权限码 <a class="header-anchor" href="#权限码" aria-label="Permalink to &quot;权限码&quot;">​</a></h2><p>前缀 <code>print-template:</code>（<code>Domain/Permissions/PrintingPermissionCodes.cs</code>）：<code>read</code> / <code>create</code> / <code>update</code> / <code>status</code> / <code>delete</code> / <code>use</code> 可授予租户（模块角色权限种子默认授 <code>tenant_admin</code>）；<code>global-manage</code> 为平台专属（管理全局模板与租户开放状态，经 <code>SaasPlatformPermissions.ContributePlatformOnly</code> 登记进统一排除口径）。</p><h2 id="数据源目录" tabindex="-1">数据源目录 <a class="header-anchor" href="#数据源目录" aria-label="Permalink to &quot;数据源目录&quot;">​</a></h2><p>模板可绑定「代码注册数据源」获得字段素材与样例数据。目录以<strong>后端注册表为单一事实源</strong>（<code>Domain/DataSources/IPrintDataSourceRegistry</code>）：</p><ul><li><strong>注册</strong>：业务模块在自己的 <code>ConfigureServices</code> 中调 <code>services.RegisterPrintDataSource(definition)</code> 登记定义（字段契约 + 静态样例 JSON）；打印模块内置示例数据源 <code>system.print-demo</code> 随模块自注册。</li><li><strong>启动期校验</strong>：应用启动即收纳全部登记项，重复编码、非法字段契约（未知类型/重复字段/空列明细/非法控件类型）、坏样例 JSON（不可解析或根节点不是对象/数组）都会让启动直接失败。</li><li><strong>查询</strong>：<code>GET /PrintDataSourceQuery/List</code> 输出目录，持 <code>print-template:read</code> 或 <code>print-template:use</code> 任一权限即可访问（分别服务模板管理与业务打印两条路径）。</li><li><strong>写路径 fail-closed</strong>：创建/更新模板时绑定未注册的 <code>DataSourceCode</code> 直接被拒；解析读路径不校验（既有模板宽限，前端打印使用点仍会按未注册报错）。</li><li><strong>前端惰性拉取</strong>：设计器与打印路径首次用到目录时经上面的查询端点拉取并并入本地注册表（自由模板打印不依赖目录）；<code>registerPrintDataSource</code> 仍可用于纯前端数据源；单个坏目录项只跳过自身、不影响其余数据源。</li></ul><p>由此推出的两条约束：</p><ul><li>数据源随后端代码发版，删除/改名会使既有模板的绑定失效（打印时报「数据源未注册」）；</li><li>不绑数据源的「自由模板」按模板内标准字段绑定推断样例表单，不受上述影响。</li></ul><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li><code>previewPrintByCode</code> 的完成信号仅表示预览调用已发起，无法得知用户在系统对话框中点了打印还是取消（上游引擎限制）；</li><li>直打依赖的打印机名单来自客户端所在机器，跨机器无共享；打印机偏好存浏览器 <code>localStorage</code>（按 用户×租户×模板 隔离，不上传服务端）。</li></ul>',18)])])}const g=t(a,[["render",c]]);export{u as __pageData,g as default};
